INSERT INTO Animes(anime_id, title, rating, category_id, description, image) VALUES (1, "Demon Slayer", "9.5", 1, " ยุคไทโชในญี่ปุ่น ทันจิโร่ เด็กหนุ่มใจดีที่ขายถ่านไม้เป็นอาชีพ พบว่าครอบครัวของเขาถูกปีศาจสังหาร และที่เลวร้ายไปกว่านั้น น้องสาวของเขา เนซึโกะ ผู้รอดชีวิตเพียงคนเดียว ก็ถูกอสูรสังหารเช่นกัน แม้จะเสียใจกับความจริงอันเลวร้ายนี้ ทันจิโร่ก็ตัดสินใจที่จะเป็น นักล่าอสูรเพื่อที่เขาจะได้เปลี่ยนน้องสาวของเขาให้กลับเป็นมนุษย์อีกครั้ง และฆ่าปีศาจที่สังหารครอบครัวของเขา", 'anime1.jpg'),
(2, "Attack on Titan", "9.3", 1, " หลายร้อยปีก่อน มนุษย์เกือบถูกไททันกำจัด ไททันมักมีความสูงหลายชั้น ดูเหมือนไม่มีสติปัญญา กัดกินมนุษย์ และที่แย่ที่สุดก็คือ ดูเหมือนจะทำเพื่อความสุขมากกว่าเป็นแหล่งอาหาร มนุษย์จำนวนเล็กน้อยรอดชีวิตมาได้ด้วยการสร้างกำแพงล้อมรอบเมืองที่ป้องกันด้วยกำแพงสูงมาก สูงกว่าไททันที่ใหญ่ที่สุดเสียอีก", 'anime2.jpg'),
(3, "Jujutsu Kaisen", "9.0", 1, " อิทาโดริ ยูจิเป็นเด็กชายที่มีพละกำลังมหาศาล แม้ว่าเขาจะใช้ชีวิตในโรงเรียนมัธยมที่ธรรมดามากก็ตาม วันหนึ่ง เพื่อช่วยชีวิตเพื่อนที่ถูกคำสาปโจมตี เขาจึงกินนิ้วของภูตผีสองหน้า ทำให้คำสาปนั้นฝังอยู่ในวิญญาณของเขาเอง นับจากนั้นเป็นต้นมา เขาก็แบ่งปันร่างเดียวกับภูตผีสองหน้า อิทาโดริได้รับการชี้นำจากนักเวทมนตร์ผู้ทรงพลังที่สุด โกะโจ ซาโตรุ และได้เข้าเรียนในโรงเรียนมัธยมเทคนิคแห่งเวทมนตร์โตเกียวเมโทรโพลิแทน ซึ่งเป็นองค์กรที่ต่อสู้กับคำสาป... และนั่นคือจุดเริ่มต้นของเรื่องราวอันกล้าหาญของเด็กชายที่กลายเป็นคำสาปเพื่อขับไล่คำสาป ชีวิตที่เขาไม่สามารถหันหลังกลับได้", 'anime3.jpg'),
(4, "One Piece", "8.9", 1, "  โกลด์ โรเจอร์ เป็นที่รู้จักในนามราชาโจรสลัด ผู้แข็งแกร่งที่สุดและมีชื่อเสียงฉาวโฉ่ที่สุดที่เคยล่องเรือในแกรนด์ไลน์ การจับกุมและการตายของโรเจอร์โดยรัฐบาลโลกทำให้เกิดการเปลี่ยนแปลงไปทั่วโลก คำพูดสุดท้ายของเขาก่อนเสียชีวิตได้เปิดเผยถึงที่อยู่ของสมบัติที่ยิ่งใหญ่ที่สุดในโลก วันพีช การเปิดเผยนี้เองที่ทำให้เกิดยุคโจรสลัดขึ้น ผู้คนต่างใฝ่ฝันที่จะค้นพบวันพีช (ซึ่งสัญญาว่าจะร่ำรวยและมีชื่อเสียงอย่างไม่จำกัด) และอาจเป็นตำแหน่งที่ใครๆ ก็ปรารถนามากที่สุดสำหรับผู้ที่ค้นพบมัน นั่นคือตำแหน่งราชาโจรสลัด", 'anime4.jpg'),
(5, "My Hero Academia", "8.9", 1, "  อิซึกุ มิดอริยะ นักเรียนมัธยมต้นต้องการเป็นฮีโร่มากกว่าสิ่งอื่นใด แต่เขาไม่มีพลังแม้แต่น้อย เมื่อไม่มีโอกาสเข้าเรียนในโรงเรียนมัธยม UA ที่มีชื่อเสียงสำหรับฮีโร่รุ่นใหม่ ชีวิตของเขาจึงดูเหมือนทางตันมากขึ้นเรื่อยๆ จากนั้นการเผชิญหน้ากับออลไมท์ ฮีโร่ที่ยิ่งใหญ่ที่สุดในบรรดาพวกเขาทั้งหมดทำให้เขามีโอกาสเปลี่ยนโชคชะตาของเขา...", 'anime5.jpg'),
(6, "Sakamoto Day", "8.9", 1, " อิซึกุ มิดอริยะ นักเรียนมัธยมต้นต้องการเป็นฮีโร่มากกว่าสิ่งอื่นใด แต่เขาไม่มีพลังแม้แต่น้อย เมื่อไม่มีโอกาสเข้าเรียนในโรงเรียนมัธยม UA ที่มีชื่อเสียงสำหรับฮีโร่รุ่นใหม่ ชีวิตของเขาจึงดูเหมือนทางตันมากขึ้นเรื่อยๆ จากนั้นการเผชิญหน้ากับออลไมท์ ฮีโร่ที่ยิ่งใหญ่ที่สุดในบรรดาพวกเขาทั้งหมดทำให้เขามีโอกาสเปลี่ยนโชคชะตาของเขา...", 'anime6.png'),
(7, "Fruits Basket", "9.5", 2, " โทรุ ฮอนดะ เป็นเด็กสาวกำพร้าอายุ 16 ปีที่ได้รับเชิญให้ไปอาศัยอยู่ในบ้านของเพื่อนร่วมชั้นของเธอ โซมะ ยูกิ หนุ่มหล่อ และลูกพี่ลูกน้องของเขา เคียว วัย 16 ปี และชิกุเระ วัย 27 ปี อย่างไรก็ตาม ชายหนุ่มเหล่านี้และสมาชิกครอบครัวที่เหลือ (ทั้งใกล้ชิดและห่างไกล) ต่างก็มีคำสาป หากพวกเขาถูกกอดโดยเพศตรงข้าม พวกเขาจะกลายร่างเป็นสัตว์ตามนักษัตรจีน ทุกวันคือการผจญภัยของโทรุผู้แสนหวาน ขณะที่เธอได้รู้จักทุกคนในครอบครัวดีขึ้น (โดยเฉพาะยูกิและเคียว) ทั้งในสถานการณ์ทั่วไปและแปลกประหลาด แต่คำสาปของตระกูลโซมะนั้นไม่ใช่เรื่องตลกอย่างแน่นอน... มันยังเต็มไปด้วยความโหดร้ายและความอกหักอีกด้วย", 'anime7.jpg'),
(8, "Kaguya-sama: Love Is War", "9.3", 2, " ชิโรกาเนะ มิยูกิ และชิโนมิยะ คางูยะ ขึ้นชื่อว่าเป็นทั้งอัจฉริยะและทรงพลัง ทั้งคู่เป็นหัวหน้าโรงเรียนชูจิอินที่มีชื่อเสียงในฐานะคู่ที่สูสีกัน และทุกคนต่างก็คิดว่าพวกเขาเป็นคู่ที่เหมาะสมกันมาก ความภาคภูมิใจและความเย่อหยิ่งมีอยู่มากมาย ดังนั้นการเคลื่อนไหวที่สมเหตุสมผลเพียงอย่างเดียวคือการหลอกล่ออีกฝ่ายให้เริ่มออกเดท! ใครจะชนะในสงครามจิตวิทยาครั้งนี้ที่การเคลื่อนไหวครั้งแรกเป็นสิ่งเดียวที่สำคัญ?", 'anime8.jpg'),
(9, "Honey Lemon Soda", "9.0", 2, " อุกะ อิชิโมริ เด็กสาวเงียบขรึมและขี้อาย ได้รับฉายาว่า อิชิ ตั้งแต่สมัยมัธยมต้น เมื่อเข้าเรียนที่โรงเรียนมัธยมฮาจิมิตสึ เธอได้พบกับเด็กผู้ชายชื่อไค มิอุระ ซึ่งรูปร่างหน้าตาและบุคลิกของเขาทำให้เธอนึกถึงโซดาเลมอน เมื่อทั้งสองได้รู้จักกันมากขึ้น ความสัมพันธ์ของอุกะกับไคทำให้เธอมีความมั่นใจมากขึ้น มีเพื่อนที่โรงเรียนมากขึ้น และตระหนักว่าเธอตกหลุมรักเขาเข้าแล้ว", 'anime9.jpg'),
(10, "The Dangers in My Heart", "9.9", 2, " เคียวทาโร่หลงใหลในเรื่องการฆาตกรรมและเรื่องราวสยองขวัญต่างๆ เขาจึงมักฝันกลางวันว่าจะแสดงจินตนาการอันบิดเบี้ยวของเขาให้เพื่อนร่วมชั้นที่ไม่คาดคิดได้เห็น แต่การได้พบกับอันนะ ยามาดะ ไอดอลของชั้นเรียนที่สวยงามก็จุดประกายความมืดมนในใจของเขาขึ้นมา เรื่องนี้เป็นเรื่องราวคลาสสิกเกี่ยวกับเด็กหนุ่มต่อต้านสังคมที่ตกหลุมรักสาวฮอต แต่ทั้งคู่ก็ไม่ใช่คนแบบที่เห็นในตอนแรก เคียวทาโร่และอันนะจะท้าทายความคาดหวังที่พวกเขามีต่อกันและต่อตัวเองหรือไม่", 'anime10.jpg'),
(11, "Toradora!", "8.9", 2, " ริวจิ ทาคาสึ เป็นนักเรียนมัธยมปลายที่อ่อนโยนและรักงานบ้าน แต่ต่างจากนิสัยใจดีของเขา เขามีใบหน้าที่น่าเกรงขามซึ่งมักจะทำให้เขาถูกมองว่าเป็นเด็กเกเร ในทางกลับกัน ไทกะ ไอซากะ นักเรียนตัวเล็กเหมือนตุ๊กตา ซึ่งไม่ใช่เด็กสาวที่น่ารักและเปราะบางเลย ไทกะมีดาบไม้และบุคลิกที่กล้าหาญ ไทกะเป็นที่รู้จักทั่วทั้งโรงเรียนในชื่อ เสือมือถือ", 'anime11.jpg'),
(12, "My Dress-Up Darling", "9.9", 2, " วาคานะ โกโจ นักเรียนมัธยมปลายสนใจเรื่องเดียว นั่นคือการทำตุ๊กตาฮินะ เมื่อไม่มีใครมาแบ่งปันความหลงใหลของเขา เขาจึงมีปัญหาในการหาเพื่อนหรือแม้แต่การสนทนา แต่หลังจากที่มาริน คิตากาวะ สาวฮอตที่สุดของโรงเรียน เปิดเผยความลับของตัวเอง เขาก็ค้นพบจุดประสงค์ใหม่ของทักษะการเย็บผ้าของเขา พวกเขาจะทำให้ความฝันในการแสดงคอสเพลย์ของเธอเป็นจริง!", 'anime12.jpg'),
(13, "My Hero Academia", "8.9", 3, "  อิซึกุ มิดอริยะ นักเรียนมัธยมต้นต้องการเป็นฮีโร่มากกว่าสิ่งอื่นใด แต่เขาไม่มีพลังแม้แต่น้อย เมื่อไม่มีโอกาสเข้าเรียนในโรงเรียนมัธยม UA ที่มีชื่อเสียงสำหรับฮีโร่รุ่นใหม่ ชีวิตของเขาจึงดูเหมือนทางตันมากขึ้นเรื่อยๆ จากนั้นการเผชิญหน้ากับออลไมท์ ฮีโร่ที่ยิ่งใหญ่ที่สุดในบรรดาพวกเขาทั้งหมดทำให้เขามีโอกาสเปลี่ยนโชคชะตาของเขา...", 'anime13.jpg'),
(14, "One Piece", "8.9", 3, "  โกลด์ โรเจอร์ เป็นที่รู้จักในนามราชาโจรสลัด ผู้แข็งแกร่งที่สุดและมีชื่อเสียงฉาวโฉ่ที่สุดที่เคยล่องเรือในแกรนด์ไลน์ การจับกุมและการตายของโรเจอร์โดยรัฐบาลโลกทำให้เกิดการเปลี่ยนแปลงไปทั่วโลก คำพูดสุดท้ายของเขาก่อนเสียชีวิตได้เปิดเผยถึงที่อยู่ของสมบัติที่ยิ่งใหญ่ที่สุดในโลก วันพีช การเปิดเผยนี้เองที่ทำให้เกิดยุคโจรสลัดขึ้น ผู้คนต่างใฝ่ฝันที่จะค้นพบวันพีช (ซึ่งสัญญาว่าจะร่ำรวยและมีชื่อเสียงอย่างไม่จำกัด) และอาจเป็นตำแหน่งที่ใครๆ ก็ปรารถนามากที่สุดสำหรับผู้ที่ค้นพบมัน นั่นคือตำแหน่งราชาโจรสลัด", 'anime14.jpg'),
(15, "Naruto", "9.0", 3, " นารูโตะ อุซึมากิ นินจาผู้มีพลังเกินเหตุและหัวแข็ง อาศัยอยู่ในหมู่บ้านโคโนฮะงาคุเระ ซึ่งเป็นหมู่บ้านลี้ลับ ก่อนที่เขาจะเกิดไม่นาน ปีศาจยักษ์ที่รู้จักกันในชื่อคิวบิ หรือจิ้งจอกเก้าหาง ได้โจมตีหมู่บ้านโคโนฮะงาคุเระและสร้างความหายนะให้กับหมู่บ้าน เพื่อที่จะยุติการอาละวาดของคิวบิ ผู้นำของหมู่บ้านซึ่งเป็นโฮคาเงะรุ่นที่ 4 ได้เสียสละชีวิตของตนเองและปิดผนึกสัตว์ประหลาดไว้ในตัวของนารูโตะที่เพิ่งเกิดใหม่ นารูโตะ", 'anime15.jpg'),
(16, "One Punch Man", "8.9", 3, " ไซตามะมีงานอดิเรกที่แปลกประหลาด นั่นคือการเป็นซูเปอร์ฮีโร่ แต่ถึงแม้เขาจะทำวีรกรรมและมีพลังเหนือมนุษย์มากมาย แต่ชีวิตของเขากลับเต็มไปด้วยเงา เขามีพลังมากเกินไป จนทำให้คู่ต่อสู้ทุกคนพ่ายแพ้ด้วยหมัดเดียว", 'anime16.jpg'),
(17, "Assassination Classroom", "8.9", 3, " นักเรียนชั้นประถมศึกษาปีที่ 3-E มีภารกิจคือฆ่าครูของพวกเขาให้ได้ก่อนสำเร็จการศึกษา ครูคนนั้นได้ทำลายดวงจันทร์ไปแล้ว และสัญญาว่าจะทำลายโลกหากครูคนนั้นถูกฆ่าไม่ได้ภายในหนึ่งปี แต่นักเรียนชั้นนี้จะสามารถฆ่าสัตว์ประหลาดที่มีหนวดซึ่งสามารถไปถึงความเร็ว 20 มัคได้อย่างไร ซึ่งอาจเป็นครูที่ดีที่สุดที่พวกเขาเคยมีมา", 'anime17.jpg');
INSERT INTO Animes (anime_id, title, rating, category_id, description, image) VALUES 
(18, "Haikyuu!!", "8.9", 3, " ฮินาตะ โชโย หนุ่มร่างเล็กได้รับแรงบันดาลใจจากการชมการแข่งขันของนักวอลเลย์บอลชื่อดังที่ได้รับฉายาว่า ลิตเติ้ลไจแอนท์ ทำให้เขาฟื้นคืนชีพชมรมวอลเลย์บอลของโรงเรียนมัธยมต้นของเขาขึ้นมาได้ ทีมที่เพิ่งก่อตั้งขึ้นใหม่นี้สามารถเข้าร่วมการแข่งขันได้ แต่การแข่งขันนัดแรกกลับกลายเป็นนัดสุดท้ายเมื่อพวกเขาถูก ราชาแห่งสนาม โทบิโอะ คาเงยามะ บดขยี้จนราบคาบ ฮินาตะสาบานว่าจะแซงหน้าคาเงยามะให้ได้ และหลังจากจบการศึกษาจากโรงเรียนมัธยมต้น เขาก็เข้าร่วมทีมวอลเลย์บอลของโรงเรียนมัธยมคาราซูโนะ แต่กลับพบว่าคาเงยามะ คู่ปรับเก่าของเขากลายเป็นเพื่อนร่วมทีมของเขาไปแล้ว", 'anime18.png'),
(19, "Hunter X Hunter", "9.5", 4, " ฮันเตอร์คือคนที่เดินทางไปทั่วโลกเพื่อทำภารกิจอันตรายต่างๆ ตั้งแต่จับอาชญากรไปจนถึงค้นหาสมบัติที่สูญหายไปในดินแดนที่ไม่มีใครรู้จัก กอนเป็นเด็กชายที่พ่อหายตัวไปเมื่อนานมาแล้วในฐานะฮันเตอร์ เขาเชื่อว่าถ้าเขาสามารถเดินตามรอยพ่อได้ สักวันหนึ่งเขาอาจจะได้กลับมาอยู่ร่วมกับพ่ออีกครั้ง", 'anime19.png'),
(20, "Fullmetal Alchemist: Brotherhood", "9.3", 4, " การเล่นแร่แปรธาตุถูกผูกมัดด้วยกฎแห่งการแลกเปลี่ยนที่เท่าเทียมกัน ซึ่งพี่น้องเอ็ดเวิร์ดและอัลฟองส์ เอลริกเพิ่งจะเข้าใจหลังจากพยายามแปลงร่างเป็นมนุษย์ นั่นคือการเล่นแร่แปรธาตุต้องห้าม พวกเขาต้องจ่ายราคาที่แสนแพงสำหรับการกระทำผิดของตนเอง เอ็ดเวิร์ดต้องสูญเสียขาซ้าย อัลฟองส์ต้องสูญเสียร่างกาย การที่เขาสามารถติดวิญญาณของอัลฟองส์เข้ากับชุดเกราะได้ก็ด้วยการเสียสละแขนขวาของเอ็ดเวิร์ดอย่างสิ้นหวังเท่านั้น ความหวังที่พวกเขาทั้งคู่จะกลับคืนสู่ร่างกายเดิมในที่สุดเป็นแรงบันดาลใจให้เอ็ดเวิร์ดหาแขนขาโลหะที่เรียกว่า “ออโตเมล์” และกลายเป็นนักเล่นแร่แปรธาตุระดับรัฐ นักเล่นแร่แปรธาตุแห่งฟูลเมทัล", 'anime20.jpg'),
(21, "No Game No Life", "9.0", 4, " เบื่อหน่ายกับชีวิตและคิดว่าโลกแห่งความเป็นจริงเป็นเพียง เกมห่วยๆ โซระและชิโระ พี่น้องที่ฉลาดหลักแหลมจึงหนีเข้าไปในโลกแฟนตาซีที่เต็มไปด้วยวิดีโอเกม", 'anime21.jpg'),
(22, "Re:Zero", "8.9", 4, " ในเรื่อง Subaru Natsuki เป็นนักเรียนมัธยมปลายธรรมดาๆ ที่หลงทางในโลกคู่ขนาน ซึ่งเขาได้รับการช่วยเหลือจากหญิงสาวผมสีเงินที่สวยงาม เขาอยู่ใกล้ๆ เธอเพื่อตอบแทนบุญคุณ แต่โชคชะตาที่ทำให้เธอต้องแบกรับไว้นั้นยากเกินกว่าที่ Subaru จะจินตนาการได้ ศัตรูโจมตีทีละตัว และทั้งคู่ก็ถูกฆ่าตาย จากนั้นเขาก็พบว่าเขามีพลังในการย้อนเวลาความตายกลับไปในช่วงเวลาที่เขามาที่โลกนี้เป็นครั้งแรก แต่มีเพียงเขาเท่านั้นที่จำได้ว่าเกิดอะไรขึ้นตั้งแต่นั้นมา", 'anime22.jpg'),
(23, "The Seven Deadly Sins", "8.9", 4, " เมื่อพวกเขาถูกกล่าวหาว่าพยายามล้มล้างสถาบันกษัตริย์ นักรบผู้เป็นที่เกรงขามของเหล่าบาปทั้ง 7 จึงถูกส่งไปลี้ภัย เจ้าหญิงเอลิซาเบธได้ค้นพบความจริงว่า บาปถูกใส่ร้ายโดยอัศวินศักดิ์สิทธิ์องครักษ์ของกษัตริย์ ซึ่งสายเกินไปที่จะป้องกันไม่ให้พวกเขาลอบสังหารบิดาของเธอและยึดบัลลังก์!", 'anime23.jpg'),
(24, "Black Clover", "8.9", 4, " ในโลกที่เวทมนตร์คือทุกสิ่ง แอสต้าและยูโนะถูกพบทิ้งอยู่ที่โบสถ์ในวันเดียวกัน ในขณะที่ยูโนะได้รับพรด้วยพลังเวทมนตร์ที่พิเศษ แอสต้าเป็นคนเดียวในโลกนี้ที่ไม่มีพลังเวทมนตร์เลย เมื่ออายุได้สิบห้าปี ทั้งคู่ได้รับตำราเวทมนตร์ที่เพิ่มพลังเวทมนตร์ให้กับผู้ถือครอง ตำราเวทมนตร์ของแอสต้าเป็นตำราเวทมนตร์ต่อต้านเวทมนตร์ที่หายากซึ่งสามารถปฏิเสธและขับไล่คาถาของคู่ต่อสู้ได้ แม้จะตรงกันข้ามแต่ก็เป็นคู่แข่งที่ดี ยูโนะและแอสต้าก็พร้อมสำหรับความท้าทายที่ยากที่สุดเพื่อบรรลุความฝันร่วมกัน นั่นคือการเป็นราชาพ่อมด การยอมแพ้ไม่ใช่ทางเลือก!", 'anime24.jpg'),
(25, "Re:Zero", "8.9", 5, " ในเรื่อง Subaru Natsuki เป็นนักเรียนมัธยมปลายธรรมดาๆ ที่หลงทางในโลกคู่ขนาน ซึ่งเขาได้รับการช่วยเหลือจากหญิงสาวผมสีเงินที่สวยงาม เขาอยู่ใกล้ๆ เธอเพื่อตอบแทนบุญคุณ แต่โชคชะตาที่ทำให้เธอต้องแบกรับไว้นั้นยากเกินกว่าที่ Subaru จะจินตนาการได้ ศัตรูโจมตีทีละตัว และทั้งคู่ก็ถูกฆ่าตาย จากนั้นเขาก็พบว่าเขามีพลังในการย้อนเวลาความตายกลับไปในช่วงเวลาที่เขามาที่โลกนี้เป็นครั้งแรก แต่มีเพียงเขาเท่านั้นที่จำได้ว่าเกิดอะไรขึ้นตั้งแต่นั้นมา", 'anime25.jpg'),
(26, "Fullmetal Alchemist: Brotherhood", "9.3", 5, " การเล่นแร่แปรธาตุถูกผูกมัดด้วยกฎแห่งการแลกเปลี่ยนที่เท่าเทียมกัน ซึ่งพี่น้องเอ็ดเวิร์ดและอัลฟองส์ เอลริกเพิ่งจะเข้าใจหลังจากพยายามแปลงร่างเป็นมนุษย์ นั่นคือการเล่นแร่แปรธาตุต้องห้าม พวกเขาต้องจ่ายราคาที่แสนแพงสำหรับการกระทำผิดของตนเอง เอ็ดเวิร์ดต้องสูญเสียขาซ้าย อัลฟองส์ต้องสูญเสียร่างกาย การที่เขาสามารถติดวิญญาณของอัลฟองส์เข้ากับชุดเกราะได้ก็ด้วยการเสียสละแขนขวาของเอ็ดเวิร์ดอย่างสิ้นหวังเท่านั้น ความหวังที่พวกเขาทั้งคู่จะกลับคืนสู่ร่างกายเดิมในที่สุดเป็นแรงบันดาลใจให้เอ็ดเวิร์ดหาแขนขาโลหะที่เรียกว่า “ออโตเมล์” และกลายเป็นนักเล่นแร่แปรธาตุระดับรัฐ นักเล่นแร่แปรธาตุแห่งฟูลเมทัล", 'anime26.jpg'),
(27, "The Promised Neverland", "9.0", 5, " เอ็มม่า นอร์แมน และเรย์ เป็นเด็กที่ฉลาดที่สุดในสถานเลี้ยงเด็กกำพร้าเกรซ ฟิลด์เฮาส์ และภายใต้การดูแลของหญิงสาวที่พวกเขาเรียกว่า แม่ เด็กๆ ทุกคนต่างก็มีชีวิตที่สุขสบาย มีอาหารดีๆ เสื้อผ้าสะอาดๆ และสภาพแวดล้อมที่สมบูรณ์แบบในการเรียนรู้ อะไรจะดีไปกว่าเด็กกำพร้าอีก? แต่แล้ววันหนึ่ง เอ็มม่าและนอร์แมนก็ได้ค้นพบความจริงอันมืดมนของโลกภายนอกที่พวกเขาถูกห้ามไม่ให้มองเห็น", 'anime27.jpg'),
(28, "When They Cry", "8.9", 5, " หลังจากย้ายเข้ามาในเมืองฮินามิซาวะที่เงียบสงบ มาเอบาระ เคอิจิก็ใช้เวลาทั้งวันอย่างมีความสุขในโรงเรียนโดยมักเล่นเกมกับเพื่อน ๆ ในท้องถิ่น อย่างไรก็ตาม ภาพลักษณ์ภายนอกอาจหลอกลวงได้ วันหนึ่ง เคอิจิบังเอิญได้ยินข่าวการฆาตกรรมที่เกิดขึ้นในฮินามิซาวะ จากจุดนี้เป็นต้นไป เหตุการณ์เลวร้ายเกิดขึ้นต่อหน้าเคอิจิ เมื่อเขาได้เรียนรู้ในไม่ช้าว่าเพื่อนสนิทของเขาอาจไม่ได้เป็นอย่างที่เห็น เรื่องราวนี้อิงจากเกมลึกลับสำหรับมือสมัครเล่นของ 07th Expansion โดยเล่าผ่านสถานการณ์ต่าง ๆ", 'anime28.jpg'),
(29, "Perfect Blue", "8.9", 5, " ดาราสาวดาวรุ่งอย่าง Mima เลิกร้องเพลงเพื่อไล่ตามอาชีพนักแสดงและนางแบบ แต่แฟนๆ ของเธอยังไม่พร้อมที่จะเห็นเธอไป... Mima ได้รับกำลังใจจากผู้จัดการของเธอ จึงรับบทบาทประจำในรายการทีวีชื่อดัง แต่จู่ๆ ผู้จัดการและเพื่อนร่วมงานของเธอกลับถูกฆาตกรรม Mima ที่มีความรู้สึกผิดและถูกหลอกหลอนด้วยภาพหลอนของตัวตนในอดีตของเธอ ความเป็นจริงและจินตนาการของ Mima หลอมรวมเข้ากับความหวาดระแวงที่บ้าคลั่ง เมื่อผู้สะกดรอยตามเธอเข้ามาใกล้ ทั้งในชีวิตจริงและออนไลน์ ภัยคุกคามที่เขาสร้างไว้นั้นเป็นจริงมากกว่าที่ Mima จะรู้เสียอีก ในภาพยนตร์ระทึกขวัญทางจิตวิทยาชื่อดังเรื่องนี้ ซึ่งมักได้รับการยกย่องว่าเป็นภาพยนตร์แอนิเมชั่นที่สำคัญที่สุดเรื่องหนึ่งตลอดกาล", 'anime29.jpg'),
(30, "Parasyte", "8.9", 5, " พวกมันมาถึงในความเงียบและความมืด พวกมันลงมาจากท้องฟ้า พวกมันหิวกระหายเนื้อมนุษย์ พวกมันอยู่ทุกที่ พวกมันเป็นปรสิต สิ่งมีชีวิตต่างดาวที่ต้องรุกรานและควบคุมมนุษย์ที่อาศัยเพื่อความอยู่รอด และเมื่อพวกมันติดเชื้อเหยื่อแล้ว พวกมันสามารถแปลงร่างเป็นสิ่งมีชีวิตอันตรายใดๆ ก็ได้ที่พวกมันเลือก: สัตว์ประหลาดที่มีฟันขนาดยักษ์ ปีศาจมีปีก สิ่งมีชีวิตที่มีใบมีดแทนมือ แต่ส่วนใหญ่เลือกที่จะปกปิดจุดประสงค์อันร้ายแรงของพวกมันไว้ภายใต้ใบหน้ามนุษย์ธรรมดา ดังนั้นไม่มีใครรู้ความลับของพวกมัน ยกเว้นนักเรียนมัธยมปลายธรรมดาคนหนึ่ง ชินกำลังต่อสู้เพื่อควบคุมร่างกายของตัวเองจากปรสิตต่างดาว แต่เขาจะสามารถหาวิธีเตือนมนุษยชาติถึงความน่ากลัวที่กำลังจะมาถึงได้หรือไม่?", 'anime30.jpg'),
(31, "Assassination Classroom", "8.9", 6, " นักเรียนชั้นประถมศึกษาปีที่ 3-E มีภารกิจคือฆ่าครูของพวกเขาให้ได้ก่อนสำเร็จการศึกษา ครูคนนั้นได้ทำลายดวงจันทร์ไปแล้ว และสัญญาว่าจะทำลายโลกหากครูคนนั้นถูกฆ่าไม่ได้ภายในหนึ่งปี แต่นักเรียนชั้นนี้จะสามารถฆ่าสัตว์ประหลาดที่มีหนวดซึ่งสามารถไปถึงความเร็ว 20 มัคได้อย่างไร ซึ่งอาจเป็นครูที่ดีที่สุดที่พวกเขาเคยมีมา", 'anime31.jpg'),
(32, "Fullmetal Alchemist: Brotherhood", "9.3", 6, " การเล่นแร่แปรธาตุถูกผูกมัดด้วยกฎแห่งการแลกเปลี่ยนที่เท่าเทียมกัน ซึ่งพี่น้องเอ็ดเวิร์ดและอัลฟองส์ เอลริกเพิ่งจะเข้าใจหลังจากพยายามแปลงร่างเป็นมนุษย์ นั่นคือการเล่นแร่แปรธาตุต้องห้าม พวกเขาต้องจ่ายราคาที่แสนแพงสำหรับการกระทำผิดของตนเอง เอ็ดเวิร์ดต้องสูญเสียขาซ้าย อัลฟองส์ต้องสูญเสียร่างกาย การที่เขาสามารถติดวิญญาณของอัลฟองส์เข้ากับชุดเกราะได้ก็ด้วยการเสียสละแขนขวาของเอ็ดเวิร์ดอย่างสิ้นหวังเท่านั้น ความหวังที่พวกเขาทั้งคู่จะกลับคืนสู่ร่างกายเดิมในที่สุดเป็นแรงบันดาลใจให้เอ็ดเวิร์ดหาแขนขาโลหะที่เรียกว่า “ออโตเมล์” และกลายเป็นนักเล่นแร่แปรธาตุระดับรัฐ นักเล่นแร่แปรธาตุแห่งฟูลเมทัล", 'anime32.jpg'),
(33, "Re:Zero", "8.9", 6, " ในเรื่อง Subaru Natsuki เป็นนักเรียนมัธยมปลายธรรมดาๆ ที่หลงทางในโลกคู่ขนาน ซึ่งเขาได้รับการช่วยเหลือจากหญิงสาวผมสีเงินที่สวยงาม เขาอยู่ใกล้ๆ เธอเพื่อตอบแทนบุญคุณ แต่โชคชะตาที่ทำให้เธอต้องแบกรับไว้นั้นยากเกินกว่าที่ Subaru จะจินตนาการได้ ศัตรูโจมตีทีละตัว และทั้งคู่ก็ถูกฆ่าตาย จากนั้นเขาก็พบว่าเขามีพลังในการย้อนเวลาความตายกลับไปในช่วงเวลาที่เขามาที่โลกนี้เป็นครั้งแรก แต่มีเพียงเขาเท่านั้นที่จำได้ว่าเกิดอะไรขึ้นตั้งแต่นั้นมา", 'anime33.jpg'),
(34, "Parasyte", "8.9", 6, " พวกมันมาถึงในความเงียบและความมืด พวกมันลงมาจากท้องฟ้า พวกมันหิวกระหายเนื้อมนุษย์ พวกมันอยู่ทุกที่ พวกมันเป็นปรสิต สิ่งมีชีวิตต่างดาวที่ต้องรุกรานและควบคุมมนุษย์ที่อาศัยเพื่อความอยู่รอด และเมื่อพวกมันติดเชื้อเหยื่อแล้ว พวกมันสามารถแปลงร่างเป็นสิ่งมีชีวิตอันตรายใดๆ ก็ได้ที่พวกมันเลือก: สัตว์ประหลาดที่มีฟันขนาดยักษ์ ปีศาจมีปีก สิ่งมีชีวิตที่มีใบมีดแทนมือ แต่ส่วนใหญ่เลือกที่จะปกปิดจุดประสงค์อันร้ายแรงของพวกมันไว้ภายใต้ใบหน้ามนุษย์ธรรมดา ดังนั้นไม่มีใครรู้ความลับของพวกมัน ยกเว้นนักเรียนมัธยมปลายธรรมดาคนหนึ่ง ชินกำลังต่อสู้เพื่อควบคุมร่างกายของตัวเองจากปรสิตต่างดาว แต่เขาจะสามารถหาวิธีเตือนมนุษยชาติถึงความน่ากลัวที่กำลังจะมาถึงได้หรือไม่?", 'anime34.jpg');
INSERT INTO Animes (anime_id, title, rating, category_id, description, image) VALUES 
(35, "The Promised Neverland", "9.0", 6, " เอ็มม่า นอร์แมน และเรย์ เป็นเด็กที่ฉลาดที่สุดในสถานเลี้ยงเด็กกำพร้าเกรซ ฟิลด์เฮาส์ และภายใต้การดูแลของหญิงสาวที่พวกเขาเรียกว่า แม่ เด็กๆ ทุกคนต่างก็มีชีวิตที่สุขสบาย มีอาหารดีๆ เสื้อผ้าสะอาดๆ และสภาพแวดล้อมที่สมบูรณ์แบบในการเรียนรู้ อะไรจะดีไปกว่าเด็กกำพร้าอีก? แต่แล้ววันหนึ่ง เอ็มม่าและนอร์แมนก็ได้ค้นพบความจริงอันมืดมนของโลกภายนอกที่พวกเขาถูกห้ามไม่ให้มองเห็น", 'anime35.jpg'),
(36, "Made in Abyss", "8.9", 6, " Abyss เป็นสถานที่สุดท้ายที่ยังไม่ได้สำรวจในโลก มีสิ่งมีชีวิตแปลกประหลาดและน่าอัศจรรย์เดินเตร่อยู่ภายใน และเต็มไปด้วยโบราณวัตถุล้ำค่าที่มนุษย์ในปัจจุบันไม่สามารถสร้างขึ้นใหม่ได้ ผู้ที่กล้าสำรวจความลึกนี้จะถูกเรียกว่า นักบุกถ้ำ เด็กสาวกำพร้าชื่อริโกะอาศัยอยู่ที่ขอบถ้ำ ความฝันของเธอคือการเป็นนักล่าถ้ำเหมือนแม่ของเธอและไขปริศนาของระบบถ้ำ วันหนึ่ง ริโกะเริ่มสำรวจถ้ำและค้นพบหุ่นยนต์ที่ดูเหมือนเด็กมนุษย์", 'anime36.jpg'),
(37, "Haikyuu!!", "8.9", 7, " ฮินาตะ โชโย หนุ่มร่างเล็กได้รับแรงบันดาลใจจากการชมการแข่งขันของนักวอลเลย์บอลชื่อดังที่ได้รับฉายาว่า ลิตเติ้ลไจแอนท์ ทำให้เขาฟื้นคืนชีพชมรมวอลเลย์บอลของโรงเรียนมัธยมต้นของเขาขึ้นมาได้ ทีมที่เพิ่งก่อตั้งขึ้นใหม่นี้สามารถเข้าร่วมการแข่งขันได้ แต่การแข่งขันนัดแรกกลับกลายเป็นนัดสุดท้ายเมื่อพวกเขาถูก ราชาแห่งสนาม โทบิโอะ คาเงยามะ บดขยี้จนราบคาบ ฮินาตะสาบานว่าจะแซงหน้าคาเงยามะให้ได้ และหลังจากจบการศึกษาจากโรงเรียนมัธยมต้น เขาก็เข้าร่วมทีมวอลเลย์บอลของโรงเรียนมัธยมคาราซูโนะ แต่กลับพบว่าคาเงยามะ คู่ปรับเก่าของเขากลายเป็นเพื่อนร่วมทีมของเขาไปแล้ว", 'anime37.png'),
(38, "Kuroko no Basket", "9.3", 7, " ที่โรงเรียนมัธยมเซย์ริน นักเรียนใหม่สองคนที่เพิ่งได้รับการคัดเลือกพิสูจน์ให้เห็นว่าพวกเขาไม่ใช่ผู้เล่นบาสเกตบอลธรรมดา: ไทกะ คากามิ ผู้เล่นที่มีแววซึ่งกลับมาจากสหรัฐอเมริกา และเท็ตสึยะ คุโรโกะ นักเรียนธรรมดาที่ขาดความโดดเด่นทำให้เขาเคลื่อนไหวไปมาโดยไม่มีใครสังเกตเห็น แม้ว่าคุโรโกะจะไม่ใช่นักกีฬาหรือทำคะแนนได้เลย แต่เขาเป็นสมาชิกทีมบาสเกตบอลของโรงเรียนมัธยมเทโกะ ซึ่งเขาเล่นเป็น ผู้เล่นเงาคนที่หก ผู้ส่งบอลได้อย่างง่ายดายและช่วยเหลือเพื่อนร่วมทีม", 'anime38.jpg'),
(39, "Free!", "9.0", 7, " เรื่องราวเกี่ยวกับฮารุกะ นานาเสะ เด็กชายผู้ชื่นชอบการแช่ตัวในน้ำและว่ายน้ำมาโดยตลอด ก่อนจะจบการศึกษาชั้นประถมศึกษา เขาเคยเข้าร่วมการแข่งขันว่ายน้ำกับสมาชิกชมรมว่ายน้ำคนอื่นๆ อย่างมาโคโตะ ทาจิบานะ นางิสะ ฮาซึกิ และริน มัตสึโอกะ หลังจากได้รับชัยชนะ เด็กชายแต่ละคนก็แยกย้ายกันไป", 'anime39.png'),
(40, "Welcome to the Ballroom", "8.9", 7, " ฟูจิตะผ่านช่วงมัธยมศึกษาตอนต้นมาอย่างไร้จุดหมาย ไม่สามารถหาเพื่อนหรืออะไรก็ตามที่จะดึงดูดความสนใจของเขาได้ แล้ววันหนึ่ง เขาก็ถูกกลุ่มคนร้ายโจมตีและได้รับการช่วยเหลือจากชายลึกลับ แต่นี่ไม่ใช่ปรมาจารย์คาราเต้ แต่เป็นครูสอนเต้นรำ! ฟูจิตะยอมเข้าเรียนคลาสเบื้องต้นอย่างไม่เต็มใจ แต่กลับพบแรงบันดาลใจของเขา นั่นคือ ชิซึกุ นักเต้นวัยรุ่นผู้มีเสน่ห์นี่เป็นก้าวแรกของฟูจิตะสู่โลกของการเต้นแบบแข่งขันที่ตื่นเต้นเร้าใจ!", 'anime40.png'),
(41, "Aoashi", "8.9", 7, " อาชิโตะ อาโออิ เป็นนักฟุตบอลหนุ่มจากเมืองเล็กๆ ในญี่ปุ่นที่ใฝ่ฝันอยากจะเข้าเรียนในโรงเรียนมัธยมที่มีสโมสรฟุตบอลดีๆ ก็ต้องพังทลายลงเมื่อเขาก่อเหตุร้ายระหว่างการแข่งขันที่สำคัญของทีม ซึ่งส่งผลให้ทีมแพ้และตกรอบไป อย่างไรก็ตาม เขาไปสะดุดตากับคนสำคัญที่บังเอิญมาจากโตเกียว แล้วเรื่องราวจะเป็นอย่างไรสำหรับอาชิโตะ", 'anime41.jpg'),
(42, "Inazuma Eleven", "8.9", 7, " ตัวละครหลัก เอ็นโด มาโมรุ เป็นผู้รักษาประตูที่มีพรสวรรค์มาก และเป็นหลานชายของผู้รักษาประตูที่แข็งแกร่งที่สุดคนหนึ่งในญี่ปุ่น ซึ่งเสียชีวิตไปก่อนที่เขาจะเกิด แม้ว่าทักษะของเขาจะน่าทึ่งมาก แต่โรงเรียนของเขากลับไม่มีสโมสรฟุตบอลจริงๆ เนื่องจากสมาชิกอีก 6 คนดูเหมือนจะไม่สนใจแม้แต่ในการฝึกซ้อม แต่ทันทีที่กองหน้าลึกลับที่ชื่อโกเอนจิ ย้ายมาที่เมืองของเอ็นโด ผู้รักษาประตูหนุ่มก็ออกเดินทางเพื่อค้นหาและคัดเลือกสมาชิกสำหรับทีมฟุตบอลของเขา", 'anime42.png'),
(43, "Steins;Gate", "9.5", 8, " นักวิทยาศาสตร์บ้าโอคาเบะ รินทาโร่ อาศัยอยู่ในห้องเล็กๆ ในอากิฮาบาระ ซึ่งเขาประดิษฐ์ อุปกรณ์แห่งอนาคต ร่วมกับชินะ มายูริ เพื่อนสมัยเด็กจอมเพ้อฝันของเขา และฮาชิดะ อิตารุ แฮกเกอร์โอตาคุ ทั้งสามใช้เวลาไปกับการประดิษฐ์สิ่งประดิษฐ์ล่าสุดของพวกเขา ซึ่งก็คือ ไมโครเวฟโทรศัพท์ ที่สามารถควบคุมได้ผ่านข้อความ", 'anime43.jpg'),
(44, "Cyberpunk: Edgerunners", "9.3", 8, " Edgerunnersเป็นเรื่องราวแยกเดี่ยว 10 ตอนเกี่ยวกับเด็กเร่ร่อนที่พยายามเอาชีวิตรอดในเมืองแห่งอนาคตที่หมกมุ่นอยู่กับเทคโนโลยีและการดัดแปลงร่างกาย เมื่อมีทุกอย่างให้สูญเสีย เขาจึงเลือกที่จะมีชีวิตอยู่ต่อไปโดยการเป็นเอจรันเนอร์ ซึ่งเป็นคนนอกกฎหมายรับจ้างที่รู้จักกันในชื่อไซเบอร์พังก์", 'anime44.jpg'),
(45, "Accel World", "8.9", 8, " ในปี 2046 ฮารุยูกิ อาริตะ เป็นเด็กหนุ่มที่พบว่าตัวเองอยู่ในสังคมชั้นต่ำสุดในโรงเรียน ฮารุยูกิรู้สึกละอายใจกับชีวิตที่น่าสังเวชของเขา จึงทำได้เพียงแต่เล่นเกมเสมือนจริง แต่ทุกอย่างเปลี่ยนไปเมื่อคุโรยูกิฮิเมะ เด็กสาวที่ฮอตที่สุดในโรงเรียน แนะนำให้เขารู้จักกับโปรแกรมลึกลับที่ชื่อว่า Brain Burst และโลกเสมือนจริงที่เรียกว่า Accel World", 'anime45.jpg'),
(46, "Psycho-Pass", "8.9", 8, " เรื่องราวเกิดขึ้นหลังจาก Psycho-Pass หนึ่งปีครึ่ง หลังจากได้เรียนรู้ธรรมชาติที่แท้จริงของระบบ Sibyl แล้ว Akane Tsunemori ก็เลือกที่จะเชื่อฟังระบบ โดยเชื่อในทั้งมนุษยชาติและระเบียบกฎหมาย เธอเป็นส่วนหนึ่งของหน่วยงานตำรวจใหม่และใช้ชีวิตประจำวันในการเผชิญหน้ากับอาชญากร อย่างไรก็ตาม Akane ไม่รู้ว่ามีสัตว์ประหลาดที่จะเขย่าระบบจนถึงแกนกลางกำลังปรากฏตัวต่อหน้าเธอ", 'anime46.jpg'),
(47, "AKIRA", "9.0", 8, " เรื่องราวเกิดขึ้นในปี 2019 เป็นเวลากว่า 31 ปีแล้วนับตั้งแต่สงครามโลกครั้งที่ 3 เริ่มต้นขึ้น เด็กหนุ่มผู้มีพลังจิตอันน่าทึ่งได้หลุดพ้นจากการควบคุมตัวและบังเอิญมีแก๊งมอเตอร์ไซค์เข้ามาเกี่ยวข้องด้วย เหตุการณ์นี้ทำให้เท็ตสึโอะ สมาชิกแก๊งคนหนึ่งได้รับพลังจิต และเขาถูกกองทัพพาตัวไปทำการทดลอง จิตใจของเขาเปลี่ยนไปและตอนนี้เขากำลังมุ่งหน้าสู่เส้นทางแห่งสงครามเพื่อแก้แค้นสังคมที่เคยเรียกเขาว่าอ่อนแอ", 'anime47.jpg'),
(48, "Brynhildr in the Darkness", "8.9", 8, " มังงะต้นฉบับนั้นหมุนรอบเด็กชายมัธยมปลาย เรียวตะ มูราคามิ ผู้ซึ่งไม่สามารถลืมเพื่อนสมัยเด็กของเขาที่ปล่อยให้เสียชีวิตในอุบัติเหตุได้ ด้วยความรู้สึกว่าตนจะต้องทำตามสัญญาของพวกเขาในการพิสูจน์การมีอยู่ของมนุษย์ต่างดาว เขาจึงเงยหน้าขึ้นมองท้องฟ้าในฐานะสมาชิกของชมรมดาราศาสตร์อยู่ตลอดเวลา วันหนึ่ง เด็กผู้หญิงคนหนึ่งชื่อเนโกะ คุโรฮะ ซึ่งมีหน้าตาเหมือนกับเพื่อนสมัยเด็กของเขาเป๊ะๆ ปรากฏตัวขึ้นในฐานะนักเรียนย้ายมาใหม่ ปรากฏว่าเธอเป็นผู้ใช้เวทมนตร์ที่หนีออกจากห้องทดลองวิจัย", 'anime48.jpg');
